<template>
  <Modal class="editions" v-if="modals.edition" @close="toggleModal('edition')">
    <div v-if="!isCustom">
      <h3>{{ $t("Select an edition:") }}</h3>
      <ul class="editions">
        <li
          v-for="edition in editions"
          class="edition"
          :class="['edition-' + edition.id]"
          :key="edition.id"
          @click="setEdition(edition)"
        >
          <div class="edition-image" :style="{backgroundImage: `url(${getEditionImage(edition.id)})`}"></div>
          <span class="edition-name">{{ edition.name }}</span>
          <span class="edition-author" v-if="edition.author">{{ edition.author }}</span>
        </li>
        <li
          class="edition edition-custom"
          @click="isCustom = true"
        >
          <div class="edition-image" :style="{backgroundImage: `url(${require('../../assets/editions/custom.png')})`}"></div>
          <span class="edition-name">{{ $t("Custom Script / Characters") }}</span>
        </li>
      </ul>
    </div>
    <div class="custom" v-else>
      <h3>{{ $t("Load custom script / characters") }}</h3>
      <i18n
        path='To play with a custom script, you need to select the characters you want to play with in the official {link} and then upload the generated "custom-list.json" either directly here or provide a URL to such a hosted JSON file.'
        tag="span"
      >
        <template #link>
          <a
            href="https://bloodontheclocktower.com/script-tool/"
            target="_blank"
            >{{ $t("Script Tool") }}</a
          >
        </template>
      </i18n>
      <br />
      <br />
      <i18n
        path="To play with custom characters, please read {documentation} on how to write a custom character definition file."
      >
        <template #documentation>
          <a
            href="https://github.com/bra1n/townsquare#custom-characters"
            target="_blank"
            >{{ $t("the documentation") }}</a
          >
        </template>
      </i18n>
      <b>
        {{ $t("Only load custom JSON files from sources that you trust!") }}</b
      >
      <h3>{{ $t("Some popular custom scripts:") }}</h3>
      <ul class="scripts">
        <li
          v-for="(script, index) in scripts"
          :key="index"
          @click="handleURL(script[1])"
        >
          <span class="script-name">{{ script[0] }}</span>
          <span class="script-author">{{ script[2] }}</span>
        </li>
      </ul>
      <input
        type="file"
        ref="upload"
        accept="application/json"
        @change="handleUpload"
      />
      <div class="button-group">
        <div class="button" @click="openUpload">
          <font-awesome-icon icon="file-upload" /> {{ $t("Upload JSON") }}
        </div>
        <div class="button" @click="promptURL">
          <font-awesome-icon icon="link" /> {{ $t("Enter URL") }}
        </div>
        <div class="button" @click="isCustom = false">
          <font-awesome-icon icon="undo" /> {{ $t("Back") }}
        </div>
      </div>
    </div>
  </Modal>
</template>

<script>
import editionJSON from "../../editions";
import { mapMutations, mapState } from "vuex";
import Modal from "./Modal";

export default {
  components: {
    Modal
  },
  data: function() {
    return {
      editions: editionJSON,
      isCustom: false,
      scripts: [
        [
          "Deadly Penance Day",
          "https://gist.githubusercontent.com/david-urvoy/5cbf2a6dacf8b678cca2952c2b3c5f10/raw/e3fa9c422909b5c7a8713295fa2f1207faa23116/dpd-roles.json",
          "david-urvoy"
        ],
        [
          "Catfishing 11.1",
          "https://gist.githubusercontent.com/bra1n/8a5ec41a7bbf945f6b7dfc1cef72b569/raw/a312ab93c2f302e0ef83c8b65a4e8e82760fda3a/catfishing.json",
          "bra1n"
        ],
        [
          "On Thin Ice (Teensyville)",
          "https://gist.githubusercontent.com/bra1n/8dacd9f2abc6f428331ea1213ab153f5/raw/0cacbcaf8ed9bddae0cca25a9ada97e9958d868b/on-thin-ice.json",
          "bra1n"
        ],
        [
          "Race To The Bottom (Teensyville)",
          "https://gist.githubusercontent.com/bra1n/63e1354cb3dc9d4032bcd0623dc48888/raw/5acb0eedcc0a67a64a99c7e0e6271de0b7b2e1b2/race-to-the-bottom.json",
          "bra1n"
        ],
        [
          "Frankenstein's Mayor (Teensyville)",
          "https://gist.githubusercontent.com/bra1n/32c52b422cc01b934a4291eeb81dbcee/raw/5bf770693bbf7aff5e86601c82ca4af3222f4ba6/Frankensteins_Mayor_by_Ted.json",
          "Ted"
        ],
        [
          "Vigormortis High School (Teensyville)",
          "https://gist.githubusercontent.com/bra1n/1f65bd4a999524719d5dabe98c3c2d27/raw/22bbec6bf56a51a7459e5ae41ed47e41971c5445/VigormortisHighSchool.json",
          "bra1n"
        ],
        [
          "Everything always goes like this (Teensyville)",
          "https://cdn.discordapp.com/attachments/1061378478525657108/1503426429243625482/everything_always_goes_like_this_1.json?ex=6a034e79&is=6a01fcf9&hm=c81a32e1533ab44f2463cec33b5ac41d42e5e1e197c67fe55f9503ec13d34844&",
          "Celebix"
        ]
      ]
    };
  },
  computed: mapState(["modals"]),
  methods: {
    getEditionImage(editionId) {
      try {
        return require(`../../assets/editions/${editionId}.png`);
      } catch (e) {
        return require("../../assets/editions/custom.png");
      }
    },
    openUpload() {
      this.$refs.upload.click();
    },
    handleUpload() {
      const file = this.$refs.upload.files[0];
      if (file && file.size) {
        const reader = new FileReader();
        reader.addEventListener("load", () => {
          try {
            const roles = JSON.parse(reader.result);
            this.parseRoles(roles);
          } catch (e) {
            alert("Error reading custom script: " + e.message);
          }
          this.$refs.upload.value = "";
        });
        reader.readAsText(file);
      }
    },
    promptURL() {
      const url = prompt("Enter URL to a custom-script.json file");
      if (url) {
        this.handleURL(url);
      }
    },
    async handleURL(url) {
      const res = await fetch(url);
      if (res && res.json) {
        try {
          const script = await res.json();
          this.parseRoles(script);
        } catch (e) {
          alert("Error loading custom script: " + e.message);
        }
      }
    },
    parseRoles(roles) {
      if (!roles || !roles.length) return;
      const metaIndex = roles.findIndex(({ id }) => id === "_meta");
      let meta = {};
      if (metaIndex > -1) {
        meta = roles.splice(metaIndex, 1).pop();
      }
      this.$store.commit("setCustomRoles", roles);
      this.$store.commit(
        "setEdition",
        Object.assign({}, meta, { id: "custom" })
      );
      // check for fabled and set those too, if present
      if (roles.some(({ id }) => this.$store.state.fabled.has(id))) {
        const fabled = [];
        roles.forEach(({ id }) => {
          if (this.$store.state.fabled.has(id)) {
            fabled.push(this.$store.state.fabled.get(id));
          }
        });
        this.$store.commit("players/setFabled", { fabled });
      }
      this.isCustom = false;
    },
    ...mapMutations(["toggleModal", "setEdition"])
  }
};
</script>

